#!/usr/bin/env python3
"""Focused dashboard for GT-STC first-10 versus full-40 guidance."""

from __future__ import annotations

from pathlib import Path

from AAA_my_test import gt_stc_guidance_results_dashboard as results


def catalog() -> dict:
    payload = results._window_catalog()
    full40 = [
        variant
        for case in payload["cases"]
        for variant in case["variants"]
        if variant.get("window") == "full40"
    ]
    payload["full40_complete"] = sum(bool(row.get("video_ready")) for row in full40)
    payload["full40_metrics"] = sum(bool(row.get("metric_ready")) for row in full40)
    payload["full40_overlays"] = sum(
        bool(row.get("trajectory_overlay_ready")) for row in full40
    )
    return payload


def asset(kind: str, case: str, target: str = "", variant: str = "") -> Path | None:
    return results.asset(kind, case=case, target=target, variant=variant)


def page() -> str:
    return r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GT-STC · First 10 vs Full 40</title>
<style>
:root{--ink:#122333;--muted:#5e7385;--paper:#edf3f5;--panel:#fbfdfe;--line:#b8c9d2;--full:#145b85;--ten:#dc7d24;--cyan:#168fa3;--bad:#b44b4b;--good:#18755f;--shadow:0 16px 44px #17374d18}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:linear-gradient(90deg,#d9e5e9 1px,transparent 1px),linear-gradient(#d9e5e9 1px,transparent 1px),var(--paper);background-size:24px 24px;font:15px/1.5 "Avenir Next","Segoe UI",sans-serif}a{color:var(--full)}header{padding:34px clamp(18px,5vw,72px) 28px;background:#edf4f7f2;border-bottom:1px solid var(--line)}.back{font:700 11px ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase}.kicker{display:block;margin-top:24px;color:var(--cyan);font:700 11px ui-monospace,monospace;letter-spacing:.15em;text-transform:uppercase}h1{max-width:1050px;margin:7px 0 13px;font:800 clamp(38px,6vw,78px)/.92 "Arial Narrow","Avenir Next Condensed",sans-serif;letter-spacing:-.045em}.lead{max-width:980px;color:#40596b;font-size:17px}.rail-wrap{max-width:1120px;margin-top:25px}.rail{display:grid;grid-template-columns:repeat(40,1fr);gap:3px}.rail i{height:25px;border:1px solid #a9bdc7;background:#cedbe0;position:relative}.rail i.on{background:var(--ten);border-color:#b75f14}.rail i::after{content:attr(data-s);position:absolute;inset:0;display:grid;place-items:center;color:#fff;font:700 8px ui-monospace,monospace}.rail-labels{display:flex;justify-content:space-between;margin-top:7px;color:var(--muted);font:700 10px ui-monospace,monospace;text-transform:uppercase}main{max-width:1700px;margin:auto;padding:22px clamp(14px,4vw,56px) 80px}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.stat,.panel,.mode{background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow)}.stat{padding:16px}.stat span,.mono{font:700 10px ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.stat b{display:block;margin-top:5px;font:800 29px/1 "Arial Narrow",sans-serif}.panel{margin-top:14px;padding:18px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:end}.toolbar label{font-weight:700}.toolbar select,.toolbar button{display:block;margin-top:5px;padding:9px 12px;border:1px solid #8ea6b4;background:#fff;color:var(--ink)}.toolbar button{background:var(--full);color:#fff;cursor:pointer}.case-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:22px 0 10px}.case-head h2{margin:0;font:800 clamp(24px,3vw,38px) "Arial Narrow",sans-serif}.control-grid{display:grid;grid-template-columns:repeat(2,minmax(230px,390px));gap:12px}.mode{margin-top:12px;border-top:5px solid var(--cyan)}.mode-head{display:flex;justify-content:space-between;gap:12px;padding:14px 15px;border-bottom:1px solid var(--line)}.mode-head h3{margin:0;font:800 24px "Arial Narrow",sans-serif}.pair{display:grid;grid-template-columns:repeat(2,minmax(260px,1fr));gap:1px;background:var(--line)}.card{background:#fff;min-width:0}.card.full{border-top:5px solid var(--full)}.card.first10{border-top:5px solid var(--ten)}video,.empty{display:block;width:100%;aspect-ratio:16/9;background:#102335}.empty{display:grid;place-items:center;color:#c3d0d7;font:700 12px ui-monospace,monospace}.caption{padding:12px 14px 15px}.caption b{display:block;font-size:16px}.tag{color:var(--muted);font:700 10px ui-monospace,monospace;text-transform:uppercase}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;margin-top:9px;font:12px ui-monospace,monospace;color:#40586a}.good{color:var(--good)}.bad{color:var(--bad)}.first10 .caption{background:#fff8ef}.full .caption{background:#f2f8fb}.legend{display:flex;flex-wrap:wrap;gap:18px;margin-top:12px;padding:10px 12px;border-left:5px solid var(--cyan);background:#e8f2f4}.swatch{display:inline-block;width:22px;height:4px;margin:0 7px 3px 0}.gt{background:#29e2ee}.candidate{background:#ffa73d}.lost{background:#f34a58}.definitions{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:9px;border-bottom:1px solid #d8e2e6;vertical-align:top}th{color:var(--muted);font:700 10px ui-monospace,monospace;text-transform:uppercase}.pending{color:var(--ten)}@media(max-width:800px){.pair,.control-grid{grid-template-columns:1fr}.rail{gap:1px}.rail i::after{display:none}.case-head{align-items:flex-start;flex-direction:column}}@media(prefers-reduced-motion:no-preference){.mode{animation:up .3s ease both}@keyframes up{from{opacity:0;transform:translateY(7px)}}}</style>
</head><body><header><a class="back" href="/">← 返回 8092 总入口</a><span class="kicker">Controlled denoising-window study · seed 47326</span><h1>前 10 step，是否已经足够？</h1><p class="lead">固定 case、目标对象、latest3350 Top100 heads、λ=0.1、CFG 与初始噪声。每种约束只改变一个变量：在全部 40 个去噪 step 施加 guidance，或仅在 step 0–9 施加。</p><div class="rail-wrap"><div class="rail" id="rail"></div><div class="rail-labels"><span>高噪声 · step 0</span><span>橙色：First10 guidance</span><span>低噪声 · step 39</span></div></div></header>
<main><div class="summary" id="summary"></div><section class="panel"><div class="toolbar"><label>Case<select id="case"></select></label><label>画面<select id="view"><option value="raw">原始生成视频</option><option value="trajectory">GT / CoTracker 轨迹 Overlay</option></select></label><button id="refresh">刷新落盘状态</button><button id="replay">同步重播</button><span id="updated" class="mono">读取中</span></div><div class="legend" id="legend" hidden><span><i class="swatch gt"></i>青色：Source GT</span><span><i class="swatch candidate"></i>橙色：生成轨迹</span><span><i class="swatch lost"></i>红色：TRACK LOST</span></div><div id="content"></div></section><section class="panel"><h2>指标如何读</h2><div class="definitions"><table><thead><tr><th>指标</th><th>计算</th><th>判读</th></tr></thead><tbody><tr><td><b>ADE / D0</b></td><td>共同有效帧的对象中心距离均值 ÷ 首帧 bbox 对角线</td><td>越小越接近 Source GT 轨迹</td></tr><tr><td><b>FDE / D0</b></td><td>最后共同有效帧的对象中心距离 ÷ D0</td><td>越小表示最终位置越接近</td></tr><tr><td><b>PCK@10%D0</b></td><td>点误差小于 0.1D0 的共同可见点比例</td><td>越大越接近 Source GT</td></tr><tr><td><b>Track Loss</b></td><td>未来帧缺少足够共同可见 CoTracker 点的比例 ×100</td><td>越小越稳定；保留破坏性失败</td></tr><tr><td><b>vs Base</b></td><td>Guided 指标 − 同 seed Baseline 指标</td><td>正值表示相对 Baseline 增加</td></tr><tr><td><b>vs Full</b></td><td>First10 指标 − 对应 Full40 指标</td><td>负值表示 First10 在该误差上更小</td></tr></tbody></table></div></section></main>
<script>
const api='/api/gt-stc-first10-vs-full40',assetApi=api+'/asset',$=id=>document.getElementById(id),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),F=(v,d=3)=>v==null?'N/A':Number(v).toFixed(d);let D;
function metric(v){const m=v.metric||{};if(!v.metric_ready)return '<div class="metrics pending"><span>指标 Pending</span></div>';const full=v.window==='first10'?`<span>vs Full ΔADE ${F(v.delta_ade_vs_full40)}</span><span>vs Full ΔLoss ${F(v.delta_track_loss_vs_full40,1)}</span>`:'';return `<div class="metrics"><span class="${m.quality_pass?'good':'bad'}">Gate ${m.quality_pass?'PASS':'FAIL/N.A.'}</span><span>ADE/D0 ${F(m.ade_d0)}</span><span>FDE/D0 ${F(m.fde_d0)}</span><span>PCK10 ${F(m.pck_10pct_d0)}</span><span>TrackLoss ${F(m.future_track_loss_score_0_100,1)}</span>${v.mode==='baseline'?'':`<span>vs Base ΔADE ${F(v.delta_ade_d0)}</span><span>vs Base ΔLoss ${F(v.delta_track_loss,1)}</span>${full}`}</div>`}
function src(c,v){const view=$('view').value,first=v.window==='first10',kind=view==='trajectory'?(first?'window_first10_trajectory':'window_full_trajectory'):(first?'window_first10_generated':'window_full_generated'),ready=view==='trajectory'?v.trajectory_overlay_ready:v.video_ready;return ready?`${assetApi}?kind=${kind}&case=${encodeURIComponent(c.case)}&target=${encodeURIComponent(c.target)}&variant=${encodeURIComponent(v.name)}`:''}
function card(c,v,klass=''){const url=src(c,v),view=$('view').value;return `<article class="card ${klass}">${url?`<video controls muted playsinline preload="metadata" src="${url}"></video>`:`<div class="empty">${view==='trajectory'?'Overlay 生成中':'视频未生成'}</div>`}<div class="caption"><b>${E(v.label)}</b><span class="tag">${view==='trajectory'?'trajectory overlay':'raw video'} · seed 47326</span>${metric(v)}</div></article>`}
function sourceCard(c){const view=$('view').value,kind=view==='trajectory'?'window_trajectory_source':'window_source',ready=view==='trajectory'?c.source_trajectory_overlay_ready:c.source_video_ready,url=ready?`${assetApi}?kind=${kind}&case=${encodeURIComponent(c.case)}&target=${encodeURIComponent(c.target)}`:'';return `<article class="card">${url?`<video controls muted playsinline preload="metadata" src="${url}"></video>`:`<div class="empty">Source ${view} Pending</div>`}<div class="caption"><b>Source GT</b><span class="tag">reference</span></div></article>`}
function render(){const c=D.cases.find(x=>x.case===$('case').value)||D.cases[0];if(!c)return;const by=(mode,window)=>c.variants.find(x=>x.mode===mode&&x.window===window),baseline=by('baseline','baseline');$('legend').hidden=$('view').value!=='trajectory';let html=`<div class="case-head"><h2>${E(c.case)} · ${E(c.target)}</h2><span class="mono">Top100 · λ0.1 · fixed seed</span></div><div class="control-grid">${sourceCard(c)}${card(c,baseline)}</div>`;for(const [mode,label] of [['region','Region · tube mass'],['point','Point · tracked correspondence'],['combined','Combined · region + point']]){const full=by(mode,'full40'),ten=by(mode,'first10');html+=`<section class="mode"><div class="mode-head"><h3>${label}</h3><span class="mono">唯一变量：guidance step window</span></div><div class="pair">${card(c,full,'full')}${card(c,ten,'first10')}</div></section>`}$('content').innerHTML=html}
function summary(){$('summary').innerHTML=`<div class="stat"><span>Matrix</span><b>${D.case_count} × 3</b><small>cases × guidance modes</small></div><div class="stat"><span>Full40</span><b>${D.full40_complete}/${D.planned}</b><small>metrics ${D.full40_metrics} · overlays ${D.full40_overlays}</small></div><div class="stat"><span>First10</span><b>${D.complete}/${D.planned}</b><small>metrics ${D.metrics} · overlays ${D.overlays}</small></div><div class="stat"><span>Controlled</span><b>1 variable</b><small>guidance step window only</small></div>`}
async function load(){D=await fetch(api+'/catalog?v='+Date.now(),{cache:'no-store'}).then(r=>r.json());const old=$('case').value;$('case').innerHTML=D.cases.map(c=>`<option value="${E(c.case)}">${E(c.case)} · ${E(c.target)}</option>`).join('');if(D.cases.some(c=>c.case===old))$('case').value=old;summary();render();$('updated').textContent='last scan '+new Date().toLocaleTimeString()}
$('rail').innerHTML=Array.from({length:40},(_,i)=>`<i class="${i<10?'on':''}" data-s="${i}"></i>`).join('');$('case').onchange=render;$('view').onchange=render;$('refresh').onclick=load;$('replay').onclick=()=>document.querySelectorAll('video').forEach(v=>{v.currentTime=0;v.play().catch(()=>{})});load();setInterval(load,30000);
</script></body></html>'''
